```cpp
#include <iostream>
using namespace std;

int main() {
    int age = 25;          // Integer variable
    float price = 19.99;   // Floating-point variable
    char grade = 'A';      // Character variable

    cout << "Age: " << age << endl;
    cout << "Price: $" << price << endl;
    cout << "Grade: " << grade << endl;

    return 0;
}
```

```cpp
#include <iostream>
using namespace std;
int main() {
    int a = 5, b = 2;
    float result = a / b; // Implicit conversion (int/float → float)
    cout << "Division: " << result << endl; // Output: 2.5

    // Explicit conversion (C-style)
    int x = 10;
    float y = (float)x / 3; // Output: 3.333...
    cout << "Explicit: " << y << endl;
    return 0;
}
```

